use serde_json::{Value,json};
use std::{collections::BTreeMap,io::{self,BufRead}};
use codex_tools::{ToolSpec,ResponsesApiTool,ResponsesApiNamespace,ResponsesApiNamespaceTool,FreeformTool,FreeformToolFormat,ToolName};
use codex_code_mode::{ToolDefinition,ToolNamespaceDescription,CodeModeToolKind,ImageDetailVisibility,DeferredToolDiscovery};
mod tools { pub mod registry { pub trait CoreToolRuntime { fn cached_code_mode_definitions(&self, max:Option<usize>, first:bool)->Option<&[codex_code_mode::ToolDefinition]>; } } pub mod prepare_definitions { include!("prepare_definitions.rs"); } pub mod wait_spec { include!("wait_spec.rs"); } }
mod parse_arguments;
mod response_adapter;
mod search_arguments;
fn text(v:&Value,key:&str)->String{v[key].as_str().unwrap_or_default().to_owned()}
fn optional(v:&Value,key:&str)->Option<Value>{v.get(key).filter(|v|!v.is_null()).cloned()}
fn function(v:&Value)->ResponsesApiTool{let mut parameters:codex_tools::JsonSchema=serde_json::from_value(v.get("parameters").or(v.get("input_schema")).cloned().unwrap_or(json!({"type":"object","properties":{}}))).unwrap();parameters.mcp_input_schema_max_bytes=v["input_schema_max_bytes"].as_u64().map(|v|v as usize);ResponsesApiTool{name:text(v,"name"),description:text(v,"description"),strict:v["strict"].as_bool().unwrap_or(false),defer_loading:v["defer_loading"].as_bool(),parameters,output_schema:optional(v,"output_schema").map(Into::into)}}
fn custom(v:&Value)->FreeformTool{FreeformTool{name:text(v,"name"),description:text(v,"description"),defer_loading:v["defer_loading"].as_bool(),format:v.get("format").cloned().map(serde_json::from_value).transpose().unwrap().unwrap_or(FreeformToolFormat{r#type:"grammar".into(),syntax:v["freeform_syntax"].as_str().unwrap_or("lark").into(),definition:"start: /[\\s\\S]+/".into()})}}
fn spec(v:&Value)->ToolSpec{match v["type"].as_str().unwrap_or("function"){
 "namespace"=>ToolSpec::Namespace(ResponsesApiNamespace{name:text(v,"name"),description:text(v,"description"),tools:v["tools"].as_array().unwrap().iter().map(|v|if v["type"]=="custom"||v["kind"]=="freeform"{ResponsesApiNamespaceTool::Custom(custom(v))}else{ResponsesApiNamespaceTool::Function(function(v))}).collect()}),
 "custom"|"freeform"=>ToolSpec::Freeform(custom(v)),
 "tool_search"=>ToolSpec::ToolSearch{execution:v["execution"].as_str().unwrap_or("client").into(),description:text(v,"description"),parameters:function(v).parameters},
 "web_search"=>ToolSpec::WebSearch{external_web_access:v["external_web_access"].as_bool(),indexed_web_access:v["indexed_web_access"].as_bool(),filters:None,user_location:None,search_context_size:None,search_content_types:None},
 _=>ToolSpec::Function(function(v))}}
fn flat_spec(v:&Value)->ToolSpec{let member=if v["kind"]=="freeform"{ResponsesApiNamespaceTool::Custom(custom(v))}else{ResponsesApiNamespaceTool::Function(function(v))};match v["namespace"].as_str(){Some(ns)=>ToolSpec::Namespace(ResponsesApiNamespace{name:ns.into(),description:text(v,"namespace_description"),tools:vec![member]}),None=>match member{ResponsesApiNamespaceTool::Function(t)=>ToolSpec::Function(t),ResponsesApiNamespaceTool::Custom(t)=>ToolSpec::Freeform(t)}}}
fn raw(v:&Value)->ToolDefinition{let tool_name=ToolName::new(v["namespace"].as_str().map(str::to_owned),text(v,"name"));ToolDefinition{name:codex_tools::code_mode_name_for_tool_name(&tool_name),tool_name,description:text(v,"description"),kind:if v["kind"]=="freeform"{CodeModeToolKind::Freeform}else{CodeModeToolKind::Function},input_schema:if v["kind"]=="freeform"{None}else{Some(v.get("input_schema").cloned().unwrap_or(json!({"type":"object","properties":{}})))},input_schema_max_bytes:v["input_schema_max_bytes"].as_u64().map(|v|v as usize),output_schema:if v["kind"]=="freeform"{None}else{optional(v,"output_schema")}}}
fn prefixes(v:&Value)->Value{
 let values=v["tools"].as_array().cloned().unwrap_or_default();let mut raw=values.iter().map(raw).collect::<Vec<_>>();let mut specs=values.iter().map(flat_spec).collect::<Vec<_>>();
 let configured=optional(v,"function_prefixes").map(serde_json::from_value::<BTreeMap<String,String>>).transpose().unwrap();
 let functions=match codex_tools::FunctionsNamespaceFunctionPrefixes::new(configured.as_ref(),raw.iter().map(|t|t.tool_name.clone())){Ok(p)=>p,Err(error)=>return json!({"error":error})};
 for (definition,spec) in raw.iter_mut().zip(&mut specs){if let Some(prepared)=functions.prepare(&definition.tool_name,||spec.clone()) {let description=match &prepared{ToolSpec::Function(t)=>&t.description,ToolSpec::Freeform(t)=>&t.description,ToolSpec::Namespace(t)=>match &t.tools[0]{ResponsesApiNamespaceTool::Function(t)=>&t.description,ResponsesApiNamespaceTool::Custom(t)=>&t.description},_=>unreachable!()};definition.description=description.clone();*spec=prepared;}}
 let configured=codex_protocol::openai_models::IndirectDescriptionPrefixes{namespaces:optional(v,"namespaces").map(serde_json::from_value).transpose().unwrap(),mcp_servers:optional(v,"mcp_servers").map(serde_json::from_value).transpose().unwrap()};
 let registered=v["registered_namespaces"].as_array().cloned().unwrap_or_default();let namespaces=match codex_tools::IndirectNamespacePrefixes::new(Some(&configured),registered.iter().map(|p|(p["server"].as_str().unwrap(),p["namespace"].as_str().unwrap()))){Ok(p)=>p,Err(error)=>return json!({"error":error.to_string()})};
 let mut runtime=codex_tools::collect_code_mode_tool_definitions(&specs,None,false);for d in &mut runtime{d.input_schema=None;d.output_schema=None;}namespaces.apply_code_mode(&mut runtime);
 let mut prompt=codex_tools::collect_code_mode_exec_prompt_tool_definitions(&specs,None);let mut ns=BTreeMap::new();for value in &values{if let Some(name)=value["namespace"].as_str(){ns.insert(name.to_string(),ToolNamespaceDescription{name:name.into(),description:text(value,"namespace_description")});}}namespaces.apply_exec_prompt(&mut prompt,&mut ns);
 let description=codex_code_mode::build_exec_tool_description(&prompt,&[],&ns,30000,true,ImageDetailVisibility::Visible,DeferredToolDiscovery::Catalog,None);
 json!({"function_prepared":raw,"runtime":runtime,"prompt_description":description})
}
fn catalog_wait(v:&Value)->Value{let messages=optional(v,"model_messages").map(serde_json::from_value::<codex_protocol::openai_models::ModelMessages>).transpose().unwrap();let wait=messages.as_ref().and_then(|m|m.tools.as_ref()).and_then(|t|t.code_mode.as_ref()).and_then(|m|m.wait.as_ref());json!({"declaration":tools::wait_spec::create_wait_tool(wait.and_then(|m|m.description.as_deref()),wait.and_then(|m|m.parameters.as_deref()))})}
fn model_metadata(v:&Value)->Value{let catalog=v.get("catalog").cloned().unwrap_or_else(||json!({"models":v["models"]}));match serde_json::from_value::<codex_protocol::openai_models::ModelsResponse>(catalog){Err(error)=>json!({"error":error.to_string()}),Ok(models)=>{let rows=models.models.iter().map(|m|{let preset:codex_protocol::openai_models::ModelPreset=m.clone().into();json!({"id":m.slug,"visible":preset.show_in_picker,"supports_original":m.supports_image_detail_original,"use_responses_lite":m.use_responses_lite,"tool_mode":m.tool_mode,"model_messages":m.model_messages})}).collect::<Vec<_>>();json!({"models":rows,"roundtrip":serde_json::to_value(models).unwrap()})}}}
fn protocol_shape(v:&Value)->Value{fn roundtrip<T:serde::de::DeserializeOwned+serde::Serialize>(v:&Value)->Value{match serde_json::from_value::<T>(v.clone()){Ok(parsed)=>json!({"value":serde_json::to_value(parsed).unwrap()}),Err(error)=>json!({"error":error.to_string()})}}let value=&v["value"];match v["type"].as_str().unwrap(){"tool_name"=>roundtrip::<ToolName>(value),"tool_definition"=>roundtrip::<ToolDefinition>(value),"output_content_item"=>match serde_json::from_value::<codex_code_mode::FunctionCallOutputContentItem>(value.clone()){Ok(item)=>json!({"value":serde_json::to_value(&item).unwrap(),"adapted":response_adapter::into_function_call_output_content_items(vec![item])}),Err(error)=>json!({"error":error.to_string()})},"response_content_item"=>roundtrip::<codex_protocol::models::FunctionCallOutputContentItem>(value),"model_messages"=>roundtrip::<codex_protocol::openai_models::ModelMessages>(value),"code_mode_messages"=>match serde_json::from_value::<codex_protocol::openai_models::CodeModeToolMessages>(value.clone()){Ok(messages)=>json!({"value":serde_json::to_value(&messages).unwrap(),"wait":tools::wait_spec::create_wait_tool(messages.wait.as_ref().and_then(|m|m.description.as_deref()),messages.wait.as_ref().and_then(|m|m.parameters.as_deref())),"description":codex_code_mode::build_exec_tool_description(&[],&[],&BTreeMap::new(),30000,true,ImageDetailVisibility::Visible,DeferredToolDiscovery::Catalog,Some(&messages))}),Err(error)=>json!({"error":error.to_string()})},"indirect_prefixes"=>roundtrip::<codex_protocol::openai_models::IndirectDescriptionPrefixes>(value),"search_arguments"=>roundtrip::<codex_protocol::models::SearchToolCallParams>(value),_=>panic!("unknown protocol type")}}
fn tool_spec_shape(v:&Value)->Value{let specs=v["specs"].as_array().unwrap().iter().map(spec).collect::<Vec<_>>();let defs=codex_tools::collect_code_mode_tool_definitions(&specs,None,v["tool_description_first"].as_bool().unwrap_or(false));let roundtrip=serde_json::from_value::<Vec<ToolDefinition>>(serde_json::to_value(&defs).unwrap()).unwrap();let prepared_by_spec=specs.iter().map(|s|tools::prepare_definitions::prepare_code_mode_tool_definitions(None,||std::borrow::Cow::Borrowed(s),None,v["tool_description_first"].as_bool().unwrap_or(false)).into_owned()).collect::<Vec<_>>();json!({"api":codex_tools::create_tools_json_for_responses_api(&specs).unwrap(),"lite":codex_tools::create_tools_json_for_responses_lite(&specs).unwrap(),"raw":codex_tools::create_tools_raw_json_for_responses_api(&specs).unwrap().get(),"names":specs.iter().map(ToolSpec::name).collect::<Vec<_>>(),"definitions":roundtrip,"prepared_by_spec":prepared_by_spec})}
fn evaluate(v:&Value)->Value{match v["operation"].as_str().unwrap(){"prefixes"=>prefixes(v),"catalog_wait"=>catalog_wait(v),"tool_search_arguments"=>search_arguments::evaluate(v),"model_metadata"=>model_metadata(v),"protocol_shape"=>protocol_shape(v),"tool_spec_shape"=>tool_spec_shape(v),_=>panic!("unknown core API operation")}}
fn main(){for line in io::stdin().lock().lines(){let value:Value=serde_json::from_str(&line.unwrap()).unwrap();let result=evaluate(&value);println!("{}",json!({"id":value["id"],"result":result}));}}
